def transform(grid):
    """Turn each background cell lying between same-color cells in a row or column into 2."""
    out = [row[:] for row in grid]
    bg = grid[0][0]
    colors = {v for row in grid for v in row if v != bg}
    if not colors:
        return out
    color = max(colors, key=lambda x: sum(row.count(x) for row in grid))
    h, w = len(grid), len(grid[0])
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == color]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == color]
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
